import sys

def fibonacci(n, memo={}):
    if n in memo:
        return memo[n]
    if n <= 2:
        memo[n] = 1
        return 1
    memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo)
    return memo[n]

def main():
    data = sys.stdin.read().strip().split()
    for line in data:
        n = int(line)
        print(fibonacci(n))

if __name__ == "__main__":
    main()
